.notice .container { padding-block: .75rem; }
.hero {
  padding-block: clamp(3rem, 8vw, 6rem);
  min-height: 25rem;
  display: flex;
  align-items: center;
  background: linear-gradient(90deg, #10283de6, #10283d80), url("business.jpg") center / cover;
  color: #fff;
}
.hero h1 { font-size: clamp(2.5rem, 7vw, 4rem); }
.hero p { max-width: 38rem; margin-top: 1.25rem; font-size: 1.125rem; }
.btn, button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  max-width: 100%;
  margin-top: 1.5rem;
  padding: .75rem 1.5rem;
  background: #e99112;
  color: #10283d;
  border: 0;
  border-radius: .35rem;
  font: inherit;
  font-weight: 700;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
}
.btn:hover, button:hover { background: #f3a52f; }
a:focus-visible, button:focus-visible { outline: 3px solid currentColor; outline-offset: 4px; }
section { padding-block: clamp(2.5rem, 6vw, 4rem); }
.grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
  margin-top: 1.75rem;
}
.card {
  min-width: 0;
  background: #fff;
  padding: clamp(1.25rem, 3vw, 2rem);
  border-radius: .5rem;
  box-shadow: 0 5px 18px #00000012;
}
.card p, .contact p { margin-top: .75rem; }
.contact { border-top: 1px solid #dce2e6; }
footer { padding-block: 1.5rem; background: #10283d; color: #ddd; text-align: center; }
@media (max-width: 56rem) {
  .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 38rem) {
  .header-inner { flex-direction: column; align-items: flex-start; gap: .5rem; }
  nav { width: 100%; column-gap: 1.5rem; }
  .hero { min-height: 0; }
  .grid { grid-template-columns: minmax(0, 1fr); gap: 1rem; }
}

